def apply(it):
    """Lengthen the wrong options of one built item in place; returns True if changed. Never touches the key."""
    m = LONGER.get(it["id"])
    if not m:
        return False
    for o in it["options"]:
        if o["option_id"] != it["answer_option_id"] and o["text"] in m:
            o["text"] = m[o["text"]]
    return True
